@app.before_request
def cobitchain_require_password():
    allowed_paths = (
        "/site-access",
        "/site-logout",
        "/static",
        "/favicon.ico"
    )

    if request.path.startswith(allowed_paths):
        return None

    if session.get("cobitchain_authenticated") is True:
        return None

    return redirect("/site-access")


@app.route("/site-access", methods=["GET", "POST"])
def cobitchain_site_access():
    error = None

    if request.method == "POST":
        entered_password = request.form.get("password", "")

        if secrets.compare_digest(entered_password, COBITCHAIN_SITE_PASSWORD):
            session["cobitchain_authenticated"] = True
            return redirect("/")
        else:
            error = "Invalid password."

    return render_template_string(COBITCHAIN_ACCESS_TEMPLATE, error=error)


@app.route("/site-logout")
def cobitchain_site_logout():
    session.clear()
    return redirect("/site-access")

# ============================================================
# End COBIT-Chain Private Access Password Gate
