    if match.empty:
        return sterile_sop_Response("SOP/formula passport not found.", status=404)

    formula = match.iloc[0].to_dict()
    linked_drift = drift_df[drift_df["sop_key"].astype(str) == str(sop_key)].copy() if not drift_df.empty else drift_df

