def agenttrust_score_badge(score):
    if score >= 90:
        return f'<span class="badge green">{score} â€” Operationally Trusted</span>'
    if score >= 80:
        return f'<span class="badge yellow">{score} â€” Human-Gated Trusted</span>'
    if score >= 70:
        return f'<span class="badge orange">{score} â€” Restricted</span>'
    return f'<span class="badge red">{score} â€” Block / Escalate</span>'


