def agenttrust_incident_response_decision(severity, cyber, gxp, privacy, evidence, authority, vendor, recurrence):
    severity = severity or "high"

    if severity == "critical":
        base_score = 100
    elif severity == "high":
        base_score = 80
    elif severity == "medium":
        base_score = 55
    else:
        base_score = 30

    routes = []
    if cyber == "yes":
        routes.append("Cybersecurity / CyberArk / Access Owner")
    if gxp == "yes":
        routes.append("QA / Validation Owner")
    if privacy == "yes":
        routes.append("Privacy / Legal / Data Owner")
    if vendor == "yes":
        routes.append("Vendor Owner / Legal / Security")
    if evidence == "no":
        routes.append("Audit / Evidence Owner")
    if authority == "no":
        routes.append("Risk / Process Owner")
    if recurrence == "yes":
        routes.append("Governance Board / CAPA Owner")

    if not routes:
        routes.append("Governance Owner")

    if severity == "critical" or cyber == "yes" or gxp == "yes" or privacy == "yes":
        return base_score, "Critical Incident â€” Contain and Escalate", "red", ", ".join(routes), "Block or suspend affected agent scope, preserve evidence, route to accountable owner, and require closure evidence before reactivation."
    if authority == "no":
        return base_score, "Authority Incident â€” Block Action", "red", ", ".join(routes), "Revoke trust token, block action, update authority gate, and retest."
    if evidence == "no":
        return base_score, "Evidence Incident â€” Restrict Reliance", "orange", ", ".join(routes), "Mark replay weak, rebuild evidence package, and restrict operational reliance."
    if recurrence == "yes":
        return base_score, "Recurring Incident â€” CAPA Review", "orange", ", ".join(routes), "Open recurring issue review and determine CAPA or control redesign."
    return base_score, "Managed Incident â€” Track to Closure", "yellow", ", ".join(routes), "Document incident, preserve evidence, assign owner, and close with remediation proof."


